import { lazy } from 'react';
import { FileSignature as IcFileSignature, Globe as IcGlobe, ShieldCheck as IcShieldCheck, Users as IcUsers } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Customers & Contracts — hub page for the Service Desk menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'ServiceCustomerCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const CustomerPortalManagement = lazy(() => import('./CustomerPortalManagement'));
const ServiceContracts = lazy(() => import('./ServiceContracts'));
const OperationsWarranty = lazy(() => import('../../operations/pages/WarrantyManagement'));

export const TABS = [
  { id: 'portal', label: 'Customer Portal', icon: IcGlobe, page: 'CustomerPortalManagement', Component: CustomerPortalManagement },
  { id: 'contracts', label: 'Contracts', icon: IcFileSignature, page: 'ServiceContracts', Component: ServiceContracts },
  { id: 'warranty', label: 'Warranty', icon: IcShieldCheck, page: 'OperationsWarranty', Component: OperationsWarranty },
];

export default function ServiceCustomerCenter({ setPage }) {
  return (
    <TabHub
      icon={IcUsers}
      eyebrow="Service Desk"
      title="Customers & Contracts"
      subtitle="Self-service portal accounts, AMC contracts and warranty cover"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
